create extension if not exists pgcrypto;
create table if not exists public.mechanic_wallets(mechanic_id text primary key,balance numeric(12,2) not null default 1000,updated_at timestamptz not null default now());
create table if not exists public.service_payments(id uuid primary key default gen_random_uuid(),request_id text not null unique,mechanic_id text not null,amount numeric(12,2) not null,commission numeric(12,2) not null,payment_method text not null check(payment_method in('bkash','nagad','card','cash')),wallet_deducted numeric(12,2) not null default 0,created_at timestamptz not null default now());
alter table public.mechanic_wallets enable row level security;alter table public.service_payments enable row level security;
drop policy if exists wallet_select_own on public.mechanic_wallets;create policy wallet_select_own on public.mechanic_wallets for select to authenticated using(mechanic_id=auth.uid()::text);
drop policy if exists payments_select_own on public.service_payments;create policy payments_select_own on public.service_payments for select to authenticated using(mechanic_id=auth.uid()::text);
create or replace function public.get_mechanic_wallet(p_mechanic_id text) returns table(mechanic_id text,balance numeric,blocked boolean) language plpgsql security definer set search_path=public as $$ begin insert into mechanic_wallets(mechanic_id,balance) values(p_mechanic_id,1000) on conflict do nothing; return query select w.mechanic_id,w.balance,(w.balance<=100) from mechanic_wallets w where w.mechanic_id=p_mechanic_id; end; $$;
create or replace function public.recharge_mechanic_wallet(p_mechanic_id text,p_amount numeric) returns table(mechanic_id text,balance numeric,blocked boolean) language plpgsql security definer set search_path=public as $$ declare b numeric; begin if auth.uid() is null or auth.uid()::text<>p_mechanic_id then raise exception 'Unauthorized'; end if; if p_amount<=0 then raise exception 'Invalid amount'; end if; insert into mechanic_wallets(mechanic_id,balance) values(p_mechanic_id,1000) on conflict do nothing; update mechanic_wallets set balance=balance+round(p_amount,2),updated_at=now() where mechanic_wallets.mechanic_id=p_mechanic_id returning balance into b; return query select p_mechanic_id,b,(b<=100); end; $$;
create or replace function public.record_service_payment(p_request_id text,p_mechanic_id text,p_total_amount numeric,p_payment_method text,p_commission_rate numeric default 0.10) returns jsonb language plpgsql security definer set search_path=public as $$ declare e service_payments%rowtype; w numeric; fee numeric; earning numeric; after numeric; deducted numeric:=0; begin if auth.uid() is null then raise exception 'Authentication required';end if; select * into e from service_payments where request_id=p_request_id limit 1;if found then select balance into after from mechanic_wallets where mechanic_id=e.mechanic_id;return jsonb_build_object('success',true,'already_recorded',true,'total_amount',e.amount,'commission',e.commission,'mechanic_earning',e.amount-e.commission,'wallet_balance_after',coalesce(after,1000),'wallet_deducted',e.wallet_deducted,'payment_method',e.payment_method);end if; fee=round(p_total_amount*greatest(coalesce(p_commission_rate,0.10),0),2);earning=greatest(p_total_amount-fee,0);insert into mechanic_wallets(mechanic_id,balance) values(p_mechanic_id,1000) on conflict do nothing;select balance into w from mechanic_wallets where mechanic_id=p_mechanic_id for update;after=w;if p_payment_method='cash' then if w<=100 then raise exception 'Mechanic wallet is blocked';end if;if w<fee then raise exception 'Mechanic wallet cannot cover platform fee';end if;deducted=fee;after=round(w-fee,2);update mechanic_wallets set balance=after,updated_at=now() where mechanic_id=p_mechanic_id;end if;insert into service_payments(request_id,mechanic_id,amount,commission,payment_method,wallet_deducted) values(p_request_id,p_mechanic_id,p_total_amount,fee,p_payment_method,deducted);return jsonb_build_object('success',true,'already_recorded',false,'total_amount',p_total_amount,'commission',fee,'mechanic_earning',earning,'wallet_balance_after',after,'wallet_deducted',deducted,'payment_method',p_payment_method);end; $$;
grant execute on function public.get_mechanic_wallet(text) to authenticated;grant execute on function public.recharge_mechanic_wallet(text,numeric) to authenticated;grant execute on function public.record_service_payment(text,text,numeric,text,numeric) to authenticated;
